Implementation:
```csharp
private static IEnumerator MovePath(Transform target, Vector3[] points, float seconds)
{
    if (points == null || points.Length == 0) yield break;
    if (points.Length == 1 || seconds <= 0f) { target.position = points[points.Length-1]; yield break; }
    var elapsed = 0f;
    while (elapsed < seconds)
    {
        elapsed += Time.deltaTime;
        var t = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(elapsed / seconds));
        target.position = PointOnPath(points, t);
        yield return null;
    }
    target.position = points[points.Length - 1];
}

private static Vector3 PointOnPath(Vector3[] points, float t)
{
    var total = 0f;
    for (var i = 1; i < points.Length; i++) total += Vector3.Distance(points[i-1], points[i]);
    if (total <= 0.0001f) return points[points.Length-1];
    var distance = total * Mathf.Clamp01(t);
    for (var i = 1; i < points.Length; i++)
    {
        var segment = Vector3.Distance(points[i-1], points[i]);
        if (distance <= segment || i == points.Length-1)
        {
            var k = segment <= 0.0001f ? 1f : distance / segment;
            return Vector3.Lerp(points[i-1], points[i], Mathf.Clamp01(k));
        }
        distance -= segment;
    }
    return points[points.Length - 1];
}
```
Smoothstep easing over the whole path is fine.

